package app.noir.mobile;
import android.app.*;
import android.app.job.*;
import android.content.*;
import android.net.*;
import android.os.*;
import android.provider.Settings;
import org.json.JSONObject;

final class BackgroundSync {
 static final int JOB=702;static final ThreadLocal<Boolean> background=new ThreadLocal<>();
 static SharedPreferences device(Context c){return ProfileStore.base(c).getSharedPreferences("background-sync",0);}
 static {String[][] words={{"Keep Noir in sync in the background","حافظ على مزامنة نوار في الخلفية"},{"Android may pause Noir when it's closed. Your watched episodes and changes could reach your PC late. Allow background activity to keep them in sync.","قد يوقف أندرويد نوار مؤقتًا عند إغلاقه، فتتأخر حلقاتك المشاهدة وتغييراتك في الوصول إلى الكمبيوتر. اسمح بالنشاط في الخلفية للحفاظ على المزامنة."},{"Allow","السماح"},{"Not now","ليس الآن"},{"Background sync","المزامنة في الخلفية"},{"May be delayed by Android · Allow","قد يؤخرها أندرويد · السماح"},{"Last synced just now","آخر مزامنة الآن"},{"Last synced %d min ago","آخر مزامنة قبل %d دقيقة"},{"Last synced %d h ago","آخر مزامنة قبل %d ساعة"},{"Last synced %d days ago","آخر مزامنة قبل %d يوم"},{"Not synced yet","لم تتم المزامنة بعد"},{"in background","في الخلفية"},{"PC sync","مزامنة الكمبيوتر"}};for(String[] w:words)Loc.AR.put(w[0],w[1]);}
 static JobInfo jobInfo(Context c,String profile){PersistableBundle extras=new PersistableBundle();extras.putString("profile",profile);return new JobInfo.Builder(JOB,new ComponentName(c,SyncJobService.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(2000).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).setPersisted(true).setExtras(extras).build();}
 static void schedule(DataStore data){if(!data.paired()||TvUi.isTv(data.context))return;JobScheduler jobs=data.context.getSystemService(JobScheduler.class);if(jobs!=null)jobs.schedule(jobInfo(data.context,data.profileId));}
 static synchronized void network(Context c){DataStore data=NoirApp.data;if(data==null||!data.paired()||TvUi.isTv(c))return;SharedPreferences p=device(c);long now=System.currentTimeMillis(),last=p.getLong("networkTrigger",0);if(now>=last&&now-last<120000)return;p.edit().putLong("networkTrigger",now).apply();schedule(data);}
 static void register(Context c){if(TvUi.isTv(c))return;try{ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);if(cm==null)return;Intent intent=new Intent(c,SyncTriggerReceiver.class).setAction("app.noir.mobile.SYNC_NETWORK");PendingIntent pending=PendingIntent.getBroadcast(c,702,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);cm.registerNetworkCallback(new NetworkRequest.Builder().addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET).build(),pending);}catch(RuntimeException ignored){}}
 static boolean run(DataStore data,boolean periodic)throws Exception{background.set(true);try{if(periodic&&!data.hasOutbox()){try{JSONObject changes=data.pcRequest("/v1/changes",null);String revision=changes.optString("revision");if(!changes.optString("profile").equals(data.linkedProfile()))throw new DataStore.ProfileMismatch("");if(!revision.isEmpty()&&revision.equals(data.lastRevision())){data.synced(true);return false;}}catch(DataStore.HttpStatus e){if(e.status!=404)throw e;}}data.sync();return true;}finally{background.remove();}}
 static boolean allowed(Context c){PowerManager pm=c.getSystemService(PowerManager.class);return pm!=null&&pm.isIgnoringBatteryOptimizations(c.getPackageName());}
 static void maybeAsk(MainActivity a){if(shouldAsk(a.data.paired(),a.data.lastSync(),TvUi.isTv(a),!device(a.data.context).getBoolean("askedBattery",false)))batteryCard(a);}
 static boolean shouldAsk(boolean paired,long lastSync,boolean tv,boolean notAsked){return paired&&lastSync>0&&!tv&&notAsked;}
 static NoirSheet batteryCard(Activity a){if(TvUi.isTv(a))return null;device(a instanceof MainActivity?((MainActivity)a).data.context:a).edit().putBoolean("askedBattery",true).apply();NoirSheet sheet=new NoirSheet(a,"Keep Noir in sync in the background","Android may pause Noir when it's closed. Your watched episodes and changes could reach your PC late. Allow background activity to keep them in sync.");sheet.footer("Allow",()->allow(a),"Not now",null);sheet.show();return sheet;}
 @SuppressWarnings("BatteryLife") static void allow(Activity a){Intent request=new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+a.getPackageName()));try{if(request.resolveActivity(a.getPackageManager())!=null){a.startActivity(request);return;}}catch(RuntimeException ignored){}try{a.startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));}catch(RuntimeException ignored){}}
 static String status(DataStore data){long at=data.lastSync();if(at==0)return Loc.t("Not synced yet");long minutes=Math.max(0,(System.currentTimeMillis()-at)/60000);String line=minutes==0?Loc.t("Last synced just now"):minutes<60?Loc.f("Last synced %d min ago",minutes):minutes<1440?Loc.f("Last synced %d h ago",minutes/60):Loc.f("Last synced %d days ago",minutes/1440);return line+(data.lastSyncBackground()?" · "+Loc.t("in background"):"");}
 static void settings(MainActivity a){if(TvUi.isTv(a))return;PhoneExperience.row(a,"clock","Background sync",allowed(a)?"On":"May be delayed by Android · Allow",()->batteryCard(a));}
}
